//! Named presets: the configuration each perseus run path ran under, derived from its env dicts
//! (`presets_data.rs`, generated by `tools/derive_presets.py`). A preset is a `Config` plus the planner knobs the
//! same path exported (`PlanConfig`); callers layer their own changes with `Config::overlay`.
use crate::error::{Error, Result};
use crate::{Config, PlanConfig};

#[rustfmt::skip]
mod data {
    include!("presets_data.rs");
}

pub const NAMES: [&str; 4] = ["n32_gpt2_decode", "n32_gpt2_prefill", "n32_llama_decode", "n32_llama_prefill"];

/// The legacy env table of a preset.
pub fn table(name: &str) -> Result<&'static [(&'static str, &'static str)]> {
    Ok(match name {
        "n32_gpt2_decode" => data::N32_GPT2_DECODE,
        "n32_gpt2_prefill" => data::N32_GPT2_PREFILL,
        "n32_llama_decode" => data::N32_LLAMA_DECODE,
        "n32_llama_prefill" => data::N32_LLAMA_PREFILL,
        _ => return Err(Error::NoPreset(name.to_string(), NAMES.join(", "))),
    })
}

impl Config {
    pub fn preset(name: &str) -> Result<Config> {
        Ok(Config::from_legacy_env(table(name)?.iter().map(|(k, v)| (*k, Some(*v))))?.0)
    }
}

impl PlanConfig {
    pub fn preset(name: &str) -> Result<PlanConfig> {
        Ok(PlanConfig::from_legacy_env(table(name)?.iter().map(|(k, v)| (*k, Some(*v))))?.0)
    }
}
